  <input id="scrubber" type="range" min="0" max="100" step="0.001" value="0" aria-label="Timeline Scrubber">
</div>

<script id="rampart-strategy">
function createStrategy() {
  const cost = {bolt:50, cannon:90, frost:70, lance:120, flak:80};
  const layout = [[1,'"'bolt'],[3,'cannon'],[4,'cannon'],[13,'flak'],[11,'cannon'],[2,'cannon'],[6,'cannon'],[8,'cannon'],[12,'cannon'],[0,'cannon'],[10,'flak'],[5,'cannon'],[7,'cannon'],[9,'lance'],[14,'flak'],[15,'cannon']];
  return {
    plan(state) {
      const actions = [];
      let gold = state.gold;
      for (const [slot,type] of layout) {
        if (state.slots[slot].turret) continue;
        if (gold < cost[type]) return actions;
        actions.push({op:'build',slot,type}); gold -= cost[type];
      }
      for (const tier of [1,2]) for (const [slot,type] of layout) {
        const t = state.slots[slot].turret;
        if ("'!t || t.tier !== tier) continue;
        if (gold < tier*cost[type]) return actions;
        actions.push({op:'"'upgrade',slot}); gold -= tier*cost[type];
      }
      return actions;
    },
    target(t, enemies) {
      const splash = t.type === 'cannon' ? 90 : t.type === 'flak' ? 70 : 0;
      const damage = Math.floor(({bolt:26,cannon:60,flak:40,lance:180,frost:10})[t.type] * [0,1,1.6,2.56][t.tier]);
      let best = -1, id = enemies[0].id;
      for (const e of enemies) {
        let utility = 0;
        const priority = 1 + 350/(100+e.remaining);
        if (splash) {
          for (const n of enemies) {
            const dx=e.x-n.x, dy=e.y-n.y;
            if (dx*dx+dy*dy <= splash*splash) {
              const hit=Math.max(1,damage-n.armor);
              utility += Math.min(hit,n.hp) + (n.hp<=hit ? 15 : 0);
            }
          }
        } else {
          utility=Math.min(e.hp,Math.max(1,damage-(t.type==='lance'?0:e.armor))) + (e.air ? 12 : 0);
        }
        const score = utility*priority*(1+(e.type==='mender'?.16:0));
        if (score>best) {best=score;id=e.id;}
      }
      return id;
    }
  };
}
</script>
<script id=\"rampart-sim\">
function rampartSimulate(createStrategy, seed, maxTicks) {
  function mulberry32(a) { return function () {
    a = (a + 0x6D2B79F5) | 0; let t = Math.imul(a "'^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ''^ (t >>> 7), 61 | t)) ''^ t; return (t ''^ (t >>> 14)) >>> 0; }; }
  const random=mulberry32(seed), floor=Math.floor, strategy=createStrategy();
  const observe=rampartSimulate.observe;
  const groundPath=[[0,2],[6,2],[6,10],[12,10],[12,3],[18,3],[18,11],[23,11]];
  const airPath=[[0,6],[21,6],[21,11],[23,11]];
  const slots=[[3,3],[5,5],[7,4],[7,8],[9,9],[10,5],[11,8],[13,8],[14,5],[15,2],[16,7],[17,4],[19,8],[20,10],[22,9],[3,7]].map(([x,y],slot)=>({slot,x:x*100+50,y:y*100+50,turret:null}));
  const types=['"'grunt','runner','wisp','brute','splitter','mender','splitling'];
  const first=[1,2,3,4,6,8], weights=[10,4,3,3,2,1];
  const health=[60,40,50,150,90,70,0], speeds=[10,20,12,6,8,8,12];
  const bounty=[4,4,6,9,6,7,1], leak=[1,1,2,3,2,2,1];
  const guns=['bolt','cannon','frost','lance','flak'];
  const costs=[50,90,70,120,80], power=[26,60,10,180,40], range=[300,260,240,360,320], period=[8,24,12,36,10], splash=[0,90,0,0,70];
  let tick=0,wave=0,gold=250,baseHp=10,fallTick=-1,serial=0,enemies=[],queue=[],log=[],events=[];
  let multipliers=[0,1000], next=composition(1);
  function composition(w) {
    let n=first.filter(f=>f<=w).length, total=weights.slice(0,n).reduce((a,b)=>a+b,0);
    return Array.from({length:4+floor(3*w/5)},()=>{
      let r=random()%total,i=0;
      while(r>=weights[i]) r-=weights[i++];
      return i;
    });
  }
  function place(e) {
    const path=e.air ? airPath:groundPath;
    let distance=e.progress;
    for(let i=1;i<path.length;i++) {
      const [x,y]=path[i-1],dx=path[i][0]-x,dy=path[i][1]-y;
      const length=(Math.abs(dx)+Math.abs(dy))*100;
      if(distance<length || i===path.length-1) {
        e.x=x*100+50+Math.sign(dx)*distance; e.y=y*100+50+Math.sign(dy)*distance;
        e.dx=Math.sign(dx); e.dy=Math.sign(dy); break;
      }
      distance-=length;
    }
    e.remaining=(e.air?2600:4600)-e.progress;
  }
  function spawn(kind,w,progress=0,hp=floor(health[kind]*multipliers[w]/1000)) {
    const e={id:++serial,type:types[kind],kind,w,progress,hp,maxHp:hp,air:+(kind===2),armor:kind===0?floor(w/4):kind===3?6+w:0,speed:speeds[kind],slowed:0,age:0};
    place(e); enemies.push(e);
  }
  function view(e) {
    const {id,type,hp,maxHp,x,y,air,armor,speed,slowed,remaining}=e;
    return {id,type,hp,maxHp,x,y,air,armor,speed,slowed,remaining};
  }
  function slotView(s) {
    const t=s.turret;
    return {slot:s.slot,x:s.x,y:s.y,turret:t?{type:t.type,tier:t.tier,spent:t.spent}:null};
  }
  function event(code,x,y,other={}) {if(observe) events.push({code,x,y,...other});}
  function waveStart() {
    wave++;
    if(wave>1) multipliers[wave]=floor(multipliers[wave-1]*108/100);
    gold+=Math.min(50,floor(gold*5/100))+10+2*wave;
    const current=next; next=composition(wave+1);
    event('wave',0,2.5);
    const actions=strategy.plan({tick,wave,gold,baseHp,slots:slots.map(slotView),enemies:enemies.map(view),nextWave:next.map(i=>types[i])});
    for(const a of (Array.isArray(actions)?actions:[]).slice(0,32)) {
      if("'!a || !Number.isInteger(a.slot) || a.slot<0 || a.slot>=slots.length) continue;
      const s=slots[a.slot],t=s.turret,kind=guns.indexOf(a.type);
      if(a.op==='"'build' && "'!t && kind>=0 && gold>=costs[kind]) {
        gold-=costs[kind];s.turret={type:a.type,kind,tier:1,spent:costs[kind],cool:0,damage:power[kind],range:range[kind],angle:0};
        log.push([tick,'"'B',s.slot,kind]);event('build',s.x/100,s.y/100);
      } else if(a.op==='upgrade' && t && t.tier<3 && gold>=t.tier*costs[t.kind]) {
        const price=t.tier*costs[t.kind];gold-=price;t.spent+=price;t.tier++;t.range+=30;t.damage=floor(t.damage*16/10);
        log.push([tick,'U',s.slot,t.tier]);event('upgrade',s.x/100,s.y/100);
      } else if(a.op==='sell' && t) {
        gold+=floor(t.spent*70/100);s.turret=null;log.push([tick,'S',s.slot,0]);event('sell',s.x/100,s.y/100);
      }
    }
    current.forEach((kind,i)=>queue.push({kind,w:wave,due:tick+4*i,i}));
    queue.sort((a,b)=>a.due-b.due || a.w-b.w || a.i-b.i);
  }
  function within(a,b,r) {const dx=a.x-b.x,dy=a.y-b.y;return dx*dx+dy*dy<=r*r;}
  function allowed(t,e) {return e.air?t.kind"'!==1 && t.kind!==3:t.kind!==4;}
  function fire(s) {
    const t=s.turret;
    if (!t || (t.cool>0 && --t.cool>0)) return;
    const candidates=enemies.filter(e=>allowed(t,e)&&within(e,s,t.range));
    if(!candidates.length) return;
    const id=strategy.target && strategy.target({slot:s.slot,type:t.type,tier:t.tier,x:s.x,y:s.y,range:t.range},candidates.map(view));
    const target=candidates.find(e=>e.id===id) || candidates.reduce((a,b)=>b.remaining<a.remaining?b:a);
    if(observe) {
      t.angle=Math.atan2(target.x-s.x,target.y-s.y);
      event('"'shot',s.x/100,s.y/100,{tx:target.x/100,ty:target.y/100,air:target.air,kind:t.kind});
    }
    const hits=splash[t.kind]?enemies.filter(e=>allowed(t,e)&&within(e,target,splash[t.kind])):[target];
    for(const e of hits) {
      e.hp-=Math.max(1,t.damage-(t.kind===3?0:e.armor));
      if(t.kind===2) e.slowed=30;
    }
    t.cool=period[t.kind];
    const dead=hits.filter(e=>e.hp<=0);
    if(dead.length) {
      enemies=enemies.filter(e=>e.hp>0);
      for(const e of dead) {
        gold+=bounty[e.kind];log.push([tick,'K',e.id,s.slot]);
        event('kill',e.x/100,e.y/100,{kind:e.kind,air:e.air,id:e.id});
        if(e.kind===4) for(let j=0;j<3;j++) spawn(6,e.w,e.progress,Math.max(1,floor(e.maxHp/4)));
      }
    }
  }
  for(tick=0;tick<maxTicks;tick++) {
    if(observe) events=[];
    if(tick>=20 && (tick-20)%40===0) waveStart();
    while(queue.length && queue[0].due===tick) {const s=queue.shift();spawn(s.kind,s.w);}
    for(let i=0;i<enemies.length;i++) {
      const e=enemies[i];e.progress+=e.slowed?floor(e.speed*60/100):e.speed;place(e);
      if(e.remaining<=0) {
        baseHp-=leak[e.kind];log.push([tick,'L',e.id,baseHp]);enemies.splice(i--,1);
        event('leak',23.5,11.5,{id:e.id});
        if(baseHp<=0) {fallTick=tick;log.push([tick,'F',wave,0]);event('fall',23.5,11.5);break;}
      }
    }
    if(fallTick<0) {
      for(const e of enemies) {
        e.age++;
        if(e.kind===5 && e.age%20===0) {
          for(const n of enemies) if(within(n,e,150)) n.hp=Math.min(n.maxHp,n.hp+floor(n.maxHp*8/100));
          event('heal',e.x/100,e.y/100);
        }
      }
      for(const s of slots) fire(s);
      for(const e of enemies) if(e.slowed>0) e.slowed--;
    }
    if(observe) observe({tick,wave,gold,baseHp,events,preview:next.slice(),slots:slots.map(s=>[s.x/100,s.y/100,s.turret?.kind??-1,s.turret?.tier??0,s.turret?.angle??0]),enemies:enemies.map(e=>({id:e.id,kind:e.kind,x:e.x/100,z:e.y/100,dx:e.dx,dz:e.dy,hp:e.hp/e.maxHp,slow:e.slowed,progress:e.progress}))});
    if(fallTick>=0) break;
  }
  let hash=0x811c9dc5;
  const data=JSON.stringify(log);
  for(let i=0;i<data.length;i++) hash=Math.imul(hash"'^data.charCodeAt(i),0x01000193);
  return {score:Math.round(((fallTick<0?maxTicks:fallTick)-20)*2.5)/100,fallTick,log,hash:(hash>>>0).toString(16).padStart(8,'"'0')};
}
</script>
